mapper.update:
update ledger
set type = #{type}
    ,category = #{category}
    ,amount = #{amount}
    ,memo = #{memo}
    ,record_date  = #{recordDate}
WHERE id = #{id}

mapper.select:
SELECT
    COALESCE(SUM(amount), 0) / #{months}
FROM ledger
WHERE type = 'EXPENSE'
  AND record_date >=
      CURRENT_DATE - INTERVAL '1 month' * #{months}
